import {
  BoxGeometry,
  CircleGeometry,
  DoubleSide,
  Group,
  Mesh,
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Vector3
} from 'three/webgpu';
import {
  float,
  mix,
  smoothstep,
  uv,
  vec3
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const root = new Group();
  const resources = [];
  const primitiveCleanups = [];
  const timelines = [];
  let disposed = false;

  const spec = config.intent?.visualSpec ?? {};
  const colors = {
    ink: spec.colors?.ink ?? '#16161d',
    paper: spec.colors?.paper ?? '#e8ecf2',
    accent: spec.colors?.accent ?? '#ff2a38',
    surface: spec.colors?.surface ?? '#0b0b10'
  };

  const makeBasic = (options = {}) => {
    const material = new MeshBasicNodeMaterial(options);
    resources.push(material);
    return material;
  };

  const backdropGeometry = new PlaneGeometry(7, 6);
  const backdropMaterial = makeBasic({ side: DoubleSide });
  const backdropGradient = smoothstep(float(0.02), float(0.98), uv().y);
  backdropMaterial.colorNode = mix(
    vec3(0.043, 0.043, 0.063),
    vec3(0.086, 0.086, 0.114),
    backdropGradient
  );

  const backdrop = new Mesh(backdropGeometry, backdropMaterial);
  backdrop.position.z = -2.5;
  root.add(backdrop);

  const shadowGeometry = new CircleGeometry(1.65, 64);
  const shadowMaterial = makeBasic({
    color: colors.surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false,
    side: DoubleSide
  });
  const contactShadow = new Mesh(shadowGeometry, shadowMaterial);
  contactShadow.scale.set(1.35, 0.48, 1);
  contactShadow.position.set(0, -0.92, -0.02);
  root.add(contactShadow);

  const cardBackGeometry = new BoxGeometry(2.65, 1.82, 0.12);
  const cardBackMaterial = makeBasic({ color: colors.ink });
  const cardBack = new Mesh(cardBackGeometry, cardBackMaterial);
  cardBack.position.z = -0.08;
  root.add(cardBack);

  const cardGeometry = new PlaneGeometry(2.5, 1.67);
  const cardMaterial = makeBasic({
    color: colors.paper,
    side: DoubleSide
  });
  const card = new Mesh(cardGeometry, cardMaterial);
  card.position.z = 0.01;
  root.add(card);

  const topRailGeometry = new BoxGeometry(2.5, 0.025, 0.025);
  const accentMaterial = makeBasic({ color: colors.accent });
  const topRail = new Mesh(topRailGeometry, accentMaterial);
  topRail.position.set(0, 0.77, 0.06);
  root.add(topRail);

  const lowerRailGeometry = new BoxGeometry(0.68, 0.018, 0.018);
  const lowerRail = new Mesh(lowerRailGeometry, accentMaterial);
  lowerRail.position.set(-0.72, -0.69, 0.06);
  root.add(lowerRail);

  const cornerGeometry = new BoxGeometry(0.025, 0.34, 0.025);
  const cornerMaterial = makeBasic({ color: colors.ink });
  const corner = new Mesh(cornerGeometry, cornerMaterial);
  corner.position.set(1.13, -0.53, 0.06);
  root.add(corner);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      if (disposed) {
        texture.dispose?.();
        return;
      }
      resources.push(texture);
      cardMaterial.map = texture;
      cardMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  for (const primitive of config.cinematicPrimitives ?? []) {
    const handler = ctx.primitives?.[primitive.name];
    if (typeof handler === 'function') {
      const result = handler(root, primitive.params);
      if (result?.timeline) timelines.push(result.timeline);
      if (typeof result?.cleanup === 'function') {
        primitiveCleanups.push(result.cleanup);
      }
    }
  }

  root.userData.handlers = {};

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const cleanup of primitiveCleanups) {
      try {
        cleanup();
      } catch {}
    }

    for (const timeline of timelines) {
      try {
        timeline.kill();
      } catch {}
    }

    root.traverse((object) => {
      if (object.geometry?.dispose) object.geometry.dispose();
    });

    for (const resource of resources) {
      try {
        resource.dispose?.();
      } catch {}
    }

    root.clear();
  };

  return root;
}
